import{z as i,x as o,o as A,c as p,q as n,j as t,D as a,d as e,s as l,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"稀疏训练的数值基础","description":"","frontmatter":{"title":"稀疏训练的数值基础","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/num-sparse-training.md","filePath":"llm/num-sparse-training.md","lastUpdated":1791063341000}'),D={name:"llm/num-sparse-training.md"};function d(m,E,C,F,h,u){const r=o("Mermaid");return A(),p("div",null,[E[2]||(E[2]=n('<h1 id="稀疏训练的数值基础" tabindex="-1">稀疏训练的数值基础 <a class="header-anchor" href="#稀疏训练的数值基础" aria-label="Permalink to &quot;稀疏训练的数值基础&quot;">​</a></h1><div class="epigraph"><p>稀疏与低精度都在砍表示，砍的轴不同：一个删坐标，一个删比特；两条预算叠在同一份权重上时，账必须一起算。</p><footer>—— 据 NVIDIA 结构化稀疏白皮书与剪枝-量化联合文献整理</footer></div><p><a href="/llm/num-moe-lowprecision">上一课</a>写的是删计算（MoE 的条件路由），本课写删坐标：稀疏。剪枝与量化的路线对照在 <a href="/llm/quantization-vs-prune">量化还是剪枝</a> 已写，激活稀疏的现象与架构条件在 <a href="/llm/activation-sparsity">激活稀疏与 ReLU²</a> 已写。本课只写训练态的数值基础：打分数在哪个精度上算、掩码跳变怎么进误差账、2:4 硬件模式对训练的约束、以及稀疏与低精度叠加的次序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>稀疏训练的数值特殊性有四条。其一，打分数失真：幅度剪枝的判据 \\(|w|\\) 与 Hessian 类判据都在窄格式下失去分辨率——权重幅度与舍入噪声同量级时，排名是随机的，剪掉谁成了抽签。其二，掩码跳变：训练中动态重建掩码时，坐标的进出是离散事件，进出抖动让该坐标的动量与二阶矩统计断续作废，优化器状态对不上账。其三，2:4 模式的不动点问题：硬件稀疏张量核要求每四个连续权重恰两个非零，而梯度下降的更新不尊重这个模式——训练出的稠密权重多数时刻不满足模式，「训练全程 2:4」与「训练后投影到 2:4」是两个不同的问题。其四，叠加次序：先量化后剪枝与先剪枝后量化，误差预算不同。</p><p><span class="marginnote">术语翻译：2:4 结构化稀疏就是「每连续 4 个权重强制恰好 2 个非零」的固定格式。非零的位置可以由训练决定，但数量不能变；硬件的稀疏张量核认得这种格式，见到零就直接跳过计算，吞吐按表头翻倍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>次序原则先立：<strong>先定结构，后降精度</strong>。剪枝的打分与掩码决策在宽格式上做；掩码稳定（或按固定周期重建）之后，再对幸存权重上低精度——理由在误差预算：剪枝已经删掉了小幅度坐标，幸存权重的幅度大、离格子远，量化压力反而小，两条预算部分互补。若反过来先量化，打分数被量化噪声污染，剪枝在错的排名上做。</p><p><span class="marginnote">数字实例：权重幅度普遍在 0.01 量级、窄格式的舍入噪声也是 0.01 量级时，「A 权重 0.012、B 权重 0.011 谁更重要」这个问题完全被噪声淹没——剪掉谁等于抽签。宽格式打分的意义就是把尺子换到噪声远小于信号的量程上，排名才有意义。</span></p><p>2:4 的训练做法是投影而非约束：每步把权重块投影到满足模式的最近点（缩放配对幅度最小的两个元素），梯度穿过投影用直通。这与第四课 STE 同类：离散约束下的有偏梯度。渐进式进入——从稠密热身，逐步提高稀疏度——让优化器状态有时间跟上坐标集的变化。</p>',10)),(A(),t(s,null,{default:a(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%A8%A0%E5%AF%86%E6%9D%83%E9%87%8D%EF%BC%88%E5%AE%BD%E6%A0%BC%E5%BC%8F%EF%BC%89%22%5D%20--%3E%20SCORE%5B%22%E6%89%93%E5%88%86%EF%BC%9A%E5%AE%BD%E6%A0%BC%E5%BC%8F%E7%AE%97%E5%B9%85%E5%BA%A6%2FHessian%22%5D%0A%20%20SCORE%20--%3E%20MASK%5B%22%E5%AE%9A%E6%8E%A9%E7%A0%81%EF%BC%9A%E6%B8%90%E8%BF%9B%E6%8F%90%E9%AB%98%E7%A8%80%E7%96%8F%E5%BA%A6%22%5D%0A%20%20MASK%20--%3E%20PROJ%5B%222%3A4%20%E6%8A%95%E5%BD%B1%20%2B%20STE%20%E5%9B%9E%E4%BC%A0%22%5D%0A%20%20PROJ%20--%3E%20STAB%7B%22%E6%8E%A9%E7%A0%81%E7%A8%B3%E5%AE%9A%3F%22%7D%0A%20%20STAB%20--%3E%7C%E5%90%A6%7C%20MASK%0A%20%20STAB%20--%3E%7C%E6%98%AF%7C%20QUANT%5B%22%E5%B9%B8%E5%AD%98%E6%9D%83%E9%87%8D%E4%B8%8A%E4%BD%8E%E7%B2%BE%E5%BA%A6%22%5D%0A%20%20QUANT%20--%3E%20VERIFY%5B%22%E9%AA%8C%E6%94%B6%EF%BC%9A%E4%B8%8E%E7%A8%A0%E5%AF%86%E5%AE%BD%E5%9F%BA%E7%BA%BF%E5%90%8C%E8%A1%A8%E5%AF%B9%E7%85%A7%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[e("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,"两条预算为什么部分互补：量化的相对误差由「张量内动态范围」决定，剪枝删掉拖尾后范围收窄，同样比特数买到更细的格子——这是剪枝在先的机制根据。掩码跳变的机制账与路由翻转（上一课）同族：离散事件不进小扰动框架，但掩码跳变比路由温和——坐标进出只改局部的梯度统计，不动计算图的负载结构；固定重建周期能把离散事件变成周期扰动，优化器状态按周期归档即可。2:4 投影的机制代价：投影把两个最小幅度元素置零，若这两个元素仍在快速变化，投影等于每步注入一次结构化扰动，热身期最伤——所以渐进稀疏度不只是工程习惯，是给投影扰动降速率。",-1)),(A(),t(s,null,{default:a(()=>[l(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20GOOD%5B%22%E5%85%88%E5%89%AA%E6%9E%9D%EF%BC%8C%E5%90%8E%E9%87%8F%E5%8C%96%22%5D%0A%20%20%20%20D1%5B%22%E7%A8%A0%E5%AF%86%E5%AE%BD%E6%A0%BC%E5%BC%8F%E6%9D%83%E9%87%8D%22%5D%20--%3E%20P1%5B%22%E5%89%AA%E6%9E%9D%E5%88%A0%E6%8E%89%E6%8B%96%E5%B0%BE%E7%9A%84%E5%B0%8F%E5%B9%85%E5%9D%90%E6%A0%87%22%5D%0A%20%20%20%20P1%20--%3E%20R1%5B%22%E5%8A%A8%E6%80%81%E8%8C%83%E5%9B%B4%E6%94%B6%E7%AA%84%22%5D%0A%20%20%20%20R1%20--%3E%20Q1%5B%22%E5%90%8C%E6%A0%B7%E6%AF%94%E7%89%B9%E4%B9%B0%E5%88%B0%E6%9B%B4%E7%BB%86%E7%9A%84%E6%A0%BC%E5%AD%90%22%5D%0A%20%20%20%20Q1%20--%3E%20OK1%5B%22%E4%B8%A4%E6%9D%A1%E9%A2%84%E7%AE%97%E9%83%A8%E5%88%86%E4%BA%92%E8%A1%A5%22%5D%0A%20%20end%0A%20%20subgraph%20BAD%5B%22%E5%85%88%E9%87%8F%E5%8C%96%EF%BC%8C%E5%90%8E%E5%89%AA%E6%9E%9D%22%5D%0A%20%20%20%20D2%5B%22%E7%A8%A0%E5%AF%86%E5%AE%BD%E6%A0%BC%E5%BC%8F%E6%9D%83%E9%87%8D%22%5D%20--%3E%20Q2%5B%22%E5%85%88%E9%87%8F%E5%8C%96%EF%BC%9A%E6%89%93%E5%88%86%E6%95%B0%E8%A2%AB%E5%99%AA%E5%A3%B0%E6%B1%A1%E6%9F%93%22%5D%0A%20%20%20%20Q2%20--%3E%20P2%5B%22%E5%89%AA%E6%9E%9D%E5%9C%A8%E9%94%99%E8%AF%AF%E7%9A%84%E6%8E%92%E5%90%8D%E4%B8%8A%E5%81%9A%22%5D%0A%20%20%20%20P2%20--%3E%20OK2%5B%22%E4%B8%A4%E6%9D%A1%E9%A2%84%E7%AE%97%E4%BA%92%E7%9B%B8%E4%BC%A4%E5%AE%B3%22%5D%0A%20%20end%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">2:4 稀疏张量核的 2× 吞吐是<strong>部署侧</strong>的表头：训练时投影、掩码管理与直通的开销会把收益吃掉一大块。把表头数字直接写进训练加速的结论，是最常见的账目错误。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>训练全程稀疏对大语言模型的收益至今不是稳定结论：多数生产实践仍是「训练后剪枝 + 蒸馏回火」，本课的数值基础适用于做这个决定之前的实验。激活稀疏依赖架构：ReLU² 一类才有高激活稀疏，SwiGLU 系不算账。稀疏与量化的联合验收要同表对照：稀疏宽格式、稀疏低精度、稠密低精度、稠密宽格式四条轨，缺一条就分不清互补还是互伤。掩码本身要进检查点：掩码丢失等于模型结构丢失。</p><p><span class="marginnote">常见误区：把稀疏张量核表头的「2× 吞吐」直接当成训练提速 2 倍。那个数字是部署侧推理的；训练时还多出投影、掩码管理与直通回传的额外工作，净收益常远小于 2，规模小时甚至可能是负的。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>打分与掩码决策在宽格式；先定结构后降精度，次序错了排名是随机的。</li><li>剪枝收窄动态范围，让后续量化买到更细的格子——两条预算部分互补。</li><li>2:4 训练靠投影加 STE，渐进稀疏度是给离散扰动降速率。</li><li>掩码跳变与路由翻转同族：离散事件，用固定周期约束。</li><li>掩码进检查点；四条轨同表验收才分得清互补与互伤。</li><li>出处：NVIDIA 结构化稀疏白皮书；剪枝-量化联合文献；激活稀疏的既有课程口径。</li></ul>',6))])}const f=i(D,[["render",d]]);export{_ as __pageData,f as default};
